<template><section class="account-admin"><header><div><h1>账号管理</h1><p>创建练习账号，设置题库管理权限。</p></div><el-button type="primary" @click="openCreate">创建账号</el-button></header><el-input v-model="keyword" placeholder="搜索账号或昵称" clearable @keyup.enter="load" style="max-width:300px;margin:18px 0"/><el-table :data="rows" v-loading="busy"><el-table-column prop="studentId" label="账号"/><el-table-column prop="nickname" label="昵称"/><el-table-column label="权限"><template #default="{row}">{{roleName(row.roleCode)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'正常':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" @click="reset(row)">重置密码</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load"/><el-dialog v-model="open" :title="form.id?'编辑账号':'创建账号'" width="460px"><el-form label-position="top"><el-form-item label="账号"><el-input v-model.trim="form.studentId" :disabled="Boolean(form.id)" maxlength="32"/></el-form-item><el-form-item label="昵称"><el-input v-model.trim="form.nickname" maxlength="50"/></el-form-item><el-form-item v-if="!form.id" label="密码（至少 12 个字符）"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" maxlength="72"/></el-form-item><el-form-item label="权限"><el-select v-model="form.roleCode"><el-option label="练习用户" :value="3"/><el-option label="题库管理员" :value="2"/><el-option label="超级管理员" :value="0"/></el-select></el-form-item><el-form-item v-if="form.id" label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></section></template>
<script setup>
import {ref,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const rows=ref([]),page=ref(1),total=ref(0),keyword=ref(''),busy=ref(false),saving=ref(false),open=ref(false),form=ref({})
function roleName(n){return({0:'超级管理员',2:'题库管理员',3:'练习用户'})[n]||'管理员'}
async function load(){busy.value=true;try{const r=await request.get('/api/admin/users',{params:{page:page.value,keyword:keyword.value}});rows.value=r.data.records;total.value=Number(r.data.total)}finally{busy.value=false}}
function openCreate(){form.value={studentId:'',nickname:'',password:'',roleCode:3,status:1};open.value=true}
function edit(row){form.value={...row};open.value=true}
async function save(){saving.value=true;try{const f=form.value;if(f.id)await request.put(`/api/admin/users/${f.id}`,{nickname:f.nickname,roleCode:f.roleCode,status:f.status});else await request.post('/api/admin/users',f);open.value=false;await load();ElMessage.success('账号已保存')}finally{saving.value=false}}
async function reset(row){try{const{value}=await ElMessageBox.prompt('请输入至少 12 个字符的新密码，重置后该账号需要重新登录。',`重置 ${row.studentId} 密码`,{inputType:'password',inputValidator:v=>v?.length>=12||'密码至少 12 个字符'});await request.put(`/api/admin/users/${row.id}/password`,{password:value});ElMessage.success('密码已重置')}catch{}}
onMounted(load)
</script>
<style scoped>.account-admin{background:#fff;border:1px solid #e3e8f0;border-radius:16px;padding:24px}.account-admin header{display:flex;align-items:center;justify-content:space-between}.account-admin h1{font-size:25px;color:#283d58;margin:0 0 10px}.account-admin p{font-size:13px;color:#8193aa}.account-admin .el-pagination{margin-top:18px}</style>
